import json
d=json.load(open('pointing.json'))
out=[]
def walk(n, depth=0):
    if isinstance(n, dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='heading': out.append('\n\n## '+n.get('text','')+'\n')
        elif t=='paragraph':
            out.append('\n')
            for c in n.get('inlineContent',[]): walk(c)
            out.append('\n')
        elif t=='listItem' or t=='unorderedList' or t=='orderedList':
            if t=='listItem': out.append('\n- ')
            for c in n.get('items',n.get('content',[])): walk(c)
        elif t=='codeVoice': out.append('\`'+n.get('code','')+'\`')
        else:
            for k in ('content','inlineContent','items','primaryContentSections','sections','abstract','variants'):
                if k in n: walk(n[k])
    elif isinstance(n,list):
        for c in n: walk(c)
walk(d)
txt=''.join(out)
open('pointing.txt','w').write(txt)
print(len(txt))
